{"path": "src/semver.js", "content": "// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const va = parse(a);
  const vb = parse(b);
  for (let i = 0; i < 3; i++) {
    if (va.core[i] !== vb.core[i]) return va.core[i] < vb.core[i] ? -1 : 1;
  }
  return comparePrerelease(va.pre, vb.pre);
}

function parse(version) {
  const noBuild = String(version).split('+')[0];
  const dash = noBuild.indexOf('-');
  const corePart = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const prePart = dash === -1 ? '' : noBuild.slice(dash + 1);
  const core = corePart.split('.').map(Number);
  while (core.length < 3) core.push(0);
  return { core, pre: prePart === '' ? [] : prePart.split('.') };
}

const NUMERIC = /^\d+$/;

function comparePrerelease(pa, pb) {
  // A version without pre-release has higher precedence than one with.
  if (pa.length === 0 && pb.length === 0) return 0;
  if (pa.length === 0) return 1;
  if (pb.length === 0) return -1;
  const n = Math.min(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const x = pa[i];
    const y = pb[i];
    if (x === y) continue;
    const xNum = NUMERIC.test(x);
    const yNum = NUMERIC.test(y);
    if (xNum && yNum) {
      const bx = BigInt(x);
      const by = BigInt(y);
      if (bx !== by) return bx < by ? -1 : 1;
      continue;
    }
    // Numeric identifiers have lower precedence than alphanumeric ones.
    if (xNum) return -1;
    if (yNum) return 1;
    // Alphanumeric identifiers compare lexically in ASCII order.
    return x < y ? -1 : 1;
  }
  // A larger set of pre-release fields has higher precedence when all preceding are equal.
  if (pa.length === pb.length) return 0;
  return pa.length < pb.length ? -1 : 1;
}
"}

{"path": "test/semver.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compareVersions } from '../src/semver.js';

test('core', () => assert.equal(compareVersions('1.2.3', '1.10.0'), -1));

test('spec precedence chain (SemVer 2.0.0 §11)', () => {
  const ordered = [
    '1.0.0-alpha',
    '1.0.0-alpha.1',
    '1.0.0-alpha.beta',
    '1.0.0-beta',
    '1.0.0-beta.2',
    '1.0.0-beta.11',
    '1.0.0-rc.1',
    '1.0.0',
  ];
  for (let i = 0; i < ordered.length - 1; i++) {
    assert.equal(compareVersions(ordered[i], ordered[i + 1]), -1, `${ordered[i]} < ${ordered[i + 1]}`);
    assert.equal(compareVersions(ordered[i + 1], ordered[i]), 1, `${ordered[i + 1]} > ${ordered[i]}`);
  }
});

test('equal versions and build metadata ignored', () => {
  assert.equal(compareVersions('1.0.0-rc.1', '1.0.0-rc.1'), 0);
  assert.equal(compareVersions('1.0.0+build.1', '1.0.0+build.2'), 0);
  assert.equal(compareVersions('1.0.0-alpha+001', '1.0.0-alpha'), 0);
  assert.equal(compareVersions('1.0.0-alpha+001', '1.0.0'), -1);
});

test('pre-release does not override core comparison', () => {
  assert.equal(compareVersions('1.0.1-alpha', '1.0.0'), 1);
  assert.equal(compareVersions('2.0.0-rc.1', '1.9.9'), 1);
});

test('identifiers containing hyphens', () => {
  assert.equal(compareVersions('1.0.0-x-y.1', '1.0.0-x-y.2'), -1);
  assert.equal(compareVersions('1.0.0-alpha-1', '1.0.0-alpha'), 1);
});
